import { defineExperience, startExperience } from "@signal-lab/experience-sdk";
import { RainRecorderScene } from "./scene";
import { RainDirector } from "./director";

let scene: RainRecorderScene | null = null;
let director: RainDirector | null = null;
let root: HTMLElement | null = null;

startExperience(defineExperience({
  mount(context) {
    root = document.createElement("main");
    root.className = "rain-experience";
    root.innerHTML = `
      <div class="atmosphere" aria-hidden="true"></div>
      <section class="hero chapter" aria-labelledby="rain-title">
        <div class="copy copy--opening">
          <p class="eyebrow">窗边 · 清晨 06:18</p>
          <h1 id="rain-title">让清晨的雨，<br>被轻轻听见</h1>
          <p class="lede">透明声学膜接住每一滴雨。向下滚动，看声音如何进入同一座共振腔。</p>
          <a class="scroll-cue" href="#resonance">聆听雨声的路径 <span aria-hidden="true">↓</span></a>
        </div>
      </section>
      <section class="resonance chapter" id="resonance" aria-labelledby="resonance-title">
        <div class="copy copy--resonance">
          <p class="eyebrow">真实共振</p>
          <h2 id="resonance-title">雨滴成为声音</h2>
          <p>膜片的细微振动被共振腔温柔放大。没有合成氛围，只有此刻窗外真实的雨。</p>
        </div>
      </section>
      <section class="resolve chapter" aria-labelledby="resolve-title">
        <div class="copy copy--resolve">
          <p class="eyebrow">记录完成</p>
          <h2 id="resolve-title">保存这一刻的声音</h2>
          <p>把一场只属于今天的清晨，留在触手可及的桌面上。</p>
          <button class="primary-action" type="button">开始记录</button>
          <p class="status"><span class="status-dot" aria-hidden="true"></span> 雨声记忆已就绪</p>
        </div>
      </section>`;
    context.container.appendChild(root);

    director = new RainDirector(context.reducedMotion);
    try {
      scene = new RainRecorderScene(context.canvas, context.viewport, context.quality, context.reducedMotion);
    } catch {
      root.classList.add("webgl-fallback");
    }
  },

  update(frame) {
    const state = director?.evaluate(frame.progress, frame.pointer, frame.elapsed);
    if (state && scene) scene.render(state, frame.delta);
    if (root && state) {
      root.style.setProperty("--story-progress", state.progress.toFixed(3));
      root.dataset.phase = state.phase;
    }
  },

  resize(viewport) {
    scene?.resize(viewport);
  },

  dispose() {
    scene?.dispose();
    scene = null;
    director = null;
    root?.remove();
    root = null;
  }
}));

export type RainPhase = "arrival" | "resonance" | "memory";

export interface DirectedState {
  progress: number;
  phase: RainPhase;
  cameraX: number;
  cameraY: number;
  cameraZ: number;
  lookY: number;
  subjectX: number;
  subjectY: number;
  subjectScale: number;
  membranePulse: number;
  waveExpansion: number;
  rainActivity: number;
  chamberGlow: number;
  recordLight: number;
  pointerParallaxX: number;
  pointerParallaxY: number;
  elapsed: number;
}

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));
const smooth = (a: number, b: number, value: number): number => {
  const t = clamp01((value - a) / (b - a));
  return t * t * (3 - 2 * t);
};

export class RainDirector {
  constructor(private readonly reducedMotion: boolean) {}

  evaluate(progress: number, pointer: { x: number; y: number }, elapsed: number): DirectedState {
    const p = clamp01(progress);
    const entering = smooth(0.08, 0.48, p);
    const settling = smooth(0.64, 0.9, p);
    const resonanceWindow = entering * (1 - settling);
    const resonanceShift = smooth(0.24, 0.5, p) * (1 - smooth(0.62, 0.78, p));
    const resolveShift = smooth(0.68, 0.9, p);
    const phase: RainPhase = p < 0.32 ? "arrival" : p < 0.76 ? "resonance" : "memory";
    const parallax = this.reducedMotion ? 0 : 1 - settling;

    return {
      progress: p,
      phase,
      cameraX: -0.16 + entering * 0.32,
      cameraY: 0.1 - entering * 0.08 + settling * 0.05,
      cameraZ: 5.25 - entering * 0.42 + settling * 0.2,
      lookY: 0.02,
      subjectX: 0.62 - resonanceShift * 1.28 + resolveShift * 0.2,
      subjectY: -0.04 + entering * 0.05,
      subjectScale: 1 + entering * 0.055 - settling * 0.02,
      membranePulse: this.reducedMotion ? resonanceWindow * 0.18 : resonanceWindow,
      waveExpansion: resonanceWindow,
      rainActivity: 1 - smooth(0.68, 0.91, p),
      chamberGlow: 0.12 + entering * 0.68 - settling * 0.25,
      recordLight: smooth(0.79, 0.94, p),
      pointerParallaxX: pointer.x * 0.055 * parallax,
      pointerParallaxY: pointer.y * 0.035 * parallax,
      elapsed
    };
  }
}

import * as THREE from "three";
import type { DirectedState } from "./director";

interface ViewportShape {
  width: number;
  height: number;
  dpr: number;
}

type QualityName = "low" | "balanced" | "high";

export class RainRecorderScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly world = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(32, 1, 0.1, 40);
  private readonly subject = new THREE.Group();
  private readonly fallbackSubject = new THREE.Group();
  private subjectPlane: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | null = null;
  private readonly generatedTextures: THREE.Texture[] = [];
  private readonly rain = new THREE.Points<THREE.BufferGeometry, THREE.PointsMaterial>();
  private readonly waves: THREE.Mesh[] = [];
  private readonly glow: THREE.Sprite;
  private readonly statusLamp: THREE.Sprite;
  private readonly textureLoader = new THREE.TextureLoader();
  private subjectMaterial: THREE.MeshBasicMaterial | null = null;
  private subjectTexture: THREE.Texture | null = null;
  private readonly geometries: THREE.BufferGeometry[] = [];
  private readonly materials: THREE.Material[] = [];
  private readonly reducedMotion: boolean;
  private readonly lowQuality: boolean;
  private disposed = false;

  constructor(canvas: HTMLCanvasElement, viewport: ViewportShape, quality: QualityName, reducedMotion: boolean) {
    this.reducedMotion = reducedMotion;
    this.lowQuality = quality === "low";
    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: quality !== "low", powerPreference: "high-performance" });
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.world.fog = new THREE.FogExp2(0x334047, 0.105);

    this.glow = this.createGlowSprite(0xd09a62, 2.2, 0.18);
    this.glow.position.set(0, -0.22, -0.16);
    this.subject.add(this.glow);

    this.statusLamp = this.createGlowSprite(0xf0ad63, 0.18, 0);
    this.statusLamp.position.set(0.2, -0.43, 0.15);
    this.subject.add(this.statusLamp);

    this.createSupportingWorld();
    this.createSubjectFallback();
    this.loadApprovedSubject();
    this.world.add(this.subject);
    this.resize(viewport);
  }

  private trackGeometry<T extends THREE.BufferGeometry>(geometry: T): T {
    this.geometries.push(geometry);
    return geometry;
  }

  private trackMaterial<T extends THREE.Material>(material: T): T {
    this.materials.push(material);
    return material;
  }

  private createGlowSprite(color: number, scale: number, opacity: number): THREE.Sprite {
    const canvas = document.createElement("canvas");
    canvas.width = 128;
    canvas.height = 128;
    const context = canvas.getContext("2d");
    if (context) {
      const gradient = context.createRadialGradient(64, 64, 0, 64, 64, 64);
      gradient.addColorStop(0, "rgba(255,255,255,0.95)");
      gradient.addColorStop(0.24, "rgba(255,255,255,0.5)");
      gradient.addColorStop(0.58, "rgba(255,255,255,0.14)");
      gradient.addColorStop(1, "rgba(255,255,255,0)");
      context.fillStyle = gradient;
      context.fillRect(0, 0, 128, 128);
    }
    const texture = new THREE.CanvasTexture(canvas);
    this.generatedTextures.push(texture);
    const material = this.trackMaterial(new THREE.SpriteMaterial({ map: texture, color, transparent: true, opacity, depthTest: false, depthWrite: false, blending: THREE.AdditiveBlending }));
    const sprite = new THREE.Sprite(material);
    sprite.scale.set(scale, scale, 1);
    sprite.renderOrder = 12;
    return sprite;
  }

  private createSupportingWorld(): void {
    const count = this.lowQuality ? 36 : 86;
    const positions = new Float32Array(count * 3);
    for (let index = 0; index < count; index += 1) {
      const seed = index * 69.137;
      positions[index * 3] = ((seed * 0.73) % 7) - 3.5;
      positions[index * 3 + 1] = ((seed * 1.31) % 5.4) - 1.7;
      positions[index * 3 + 2] = -0.7 - ((seed * 0.41) % 2.8);
    }
    const rainGeometry = this.trackGeometry(new THREE.BufferGeometry());
    rainGeometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const rainMaterial = this.trackMaterial(new THREE.PointsMaterial({ color: 0xd8e0df, size: this.lowQuality ? 0.025 : 0.035, transparent: true, opacity: 0.42, depthWrite: false }));
    this.rain.geometry = rainGeometry;
    this.rain.material = rainMaterial;
    this.world.add(this.rain);

    for (let index = 0; index < 3; index += 1) {
      const geometry = this.trackGeometry(new THREE.RingGeometry(0.48 + index * 0.25, 0.488 + index * 0.25, 72));
      const material = this.trackMaterial(new THREE.MeshBasicMaterial({ color: 0xcdd8d7, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false }));
      const wave = new THREE.Mesh(geometry, material);
      wave.position.set(0, 0.18, -0.08 - index * 0.02);
      this.waves.push(wave);
      this.subject.add(wave);
    }
  }

  private createSubjectFallback(): void {
    const baseGeometry = this.trackGeometry(new THREE.CapsuleGeometry(0.72, 0.3, 6, 32));
    const baseMaterial = this.trackMaterial(new THREE.MeshStandardMaterial({ color: 0xb5aaa0, roughness: 0.9, metalness: 0.02 }));
    const base = new THREE.Mesh(baseGeometry, baseMaterial);
    base.scale.set(1.15, 0.34, 0.44);
    base.position.y = -0.52;
    this.fallbackSubject.add(base);

    const membraneGeometry = this.trackGeometry(new THREE.CircleGeometry(0.74, 72));
    const membraneMaterial = this.trackMaterial(new THREE.MeshPhysicalMaterial({ color: 0xdce4e1, transparent: true, opacity: 0.28, transmission: 0.65, roughness: 0.2, side: THREE.DoubleSide }));
    const membrane = new THREE.Mesh(membraneGeometry, membraneMaterial);
    membrane.position.set(0, 0.16, 0);
    this.fallbackSubject.add(membrane);
    this.subject.add(this.fallbackSubject);

    const light = new THREE.HemisphereLight(0xe7ece8, 0x473c34, 1.6);
    this.world.add(light);
  }

  private loadApprovedSubject(): void {
    this.textureLoader.setCrossOrigin("anonymous");
    this.textureLoader.load(
      "/creative-assets/rain-memory-recorder-v1.png",
      (texture: THREE.Texture) => {
        if (this.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.minFilter = THREE.LinearMipmapLinearFilter;
        const image = texture.image as { width?: number; height?: number };
        const width = typeof image.width === "number" && image.width > 0 ? image.width : 1;
        const height = typeof image.height === "number" && image.height > 0 ? image.height : 1;
        const aspect = width / height;
        const visualHeight = 2.9;
        const geometry = this.trackGeometry(new THREE.PlaneGeometry(visualHeight * aspect, visualHeight));
        const material = this.trackMaterial(new THREE.MeshBasicMaterial({ map: texture, transparent: true, alphaTest: 0.015, depthTest: false, depthWrite: false, toneMapped: false }));
        const plane = new THREE.Mesh(geometry, material);
        plane.position.set(0, -0.03, 0.34);
        plane.renderOrder = 20;
        plane.scale.setScalar(this.camera.aspect < 0.72 ? 0.64 : 1);
        this.subject.add(plane);
        this.fallbackSubject.visible = false;
        this.subjectPlane = plane;
        this.subjectTexture = texture;
        this.subjectMaterial = material;
      },
      undefined,
      () => {
        this.subjectTexture = null;
        this.subjectMaterial = null;
      }
    );
  }

  render(state: DirectedState, delta: number): void {
    const safeDelta = Math.min(delta, 0.05);
    this.camera.position.set(state.cameraX + state.pointerParallaxX, state.cameraY + state.pointerParallaxY, state.cameraZ);
    this.camera.lookAt(0, state.lookY, 0);
    const narrowViewport = this.camera.aspect < 0.72;
    this.subject.position.set(narrowViewport ? state.subjectX * 0.12 : state.subjectX, narrowViewport ? state.subjectY - 0.42 : state.subjectY, 0);
    this.subject.scale.setScalar(state.subjectScale);

    const vibration = this.reducedMotion ? 0 : Math.sin(state.elapsed * 18) * 0.014 * state.membranePulse;
    this.subject.rotation.x += (vibration - this.subject.rotation.x) * Math.min(1, safeDelta * 9);

    this.rain.material.opacity = 0.08 + state.rainActivity * 0.4;
    if (!this.reducedMotion) this.rain.position.y = -((state.elapsed * 0.34) % 0.7);

    for (let index = 0; index < this.waves.length; index += 1) {
      const wave = this.waves[index];
      const material = wave.material as THREE.MeshBasicMaterial;
      const offset = index * 0.16;
      const cycle = Math.max(0, Math.min(1, state.waveExpansion * 1.45 - offset));
      wave.scale.setScalar(0.72 + cycle * 0.72);
      material.opacity = state.membranePulse * Math.sin(cycle * Math.PI) * 0.19;
    }

    (this.glow.material as THREE.SpriteMaterial).opacity = state.chamberGlow * 0.34;
    (this.statusLamp.material as THREE.SpriteMaterial).opacity = state.recordLight * 0.95;
    this.renderer.render(this.world, this.camera);
  }

  resize(viewport: ViewportShape): void {
    const width = Math.max(1, viewport.width);
    const height = Math.max(1, viewport.height);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.subjectPlane?.scale.setScalar(this.camera.aspect < 0.72 ? 0.64 : 1);
    this.renderer.setPixelRatio(Math.min(viewport.dpr, this.lowQuality ? 1.25 : 2));
    this.renderer.setSize(width, height, false);
  }

  dispose(): void {
    this.disposed = true;
    this.subjectTexture?.dispose();
    for (const texture of this.generatedTextures) texture.dispose();
    this.subjectPlane = null;
    for (const geometry of this.geometries) geometry.dispose();
    for (const material of this.materials) material.dispose();
    this.renderer.dispose();
    this.renderer.forceContextLoss();
    this.world.clear();
  }
}

@import url("");

:root {
  color-scheme: dark;
  --ink: #f2efe8;
  --muted: #bdc4c1;
  --amber: #d39a5d;
  --deep: #263139;
}

*, *::before, *::after { box-sizing: border-box; }
html { margin: 0; max-width: 100%; overflow-x: hidden; scroll-behavior: smooth; background: var(--deep); }
body { margin: 0; max-width: 100%; overflow-x: clip; background: #111a1f; color: var(--ink); font-family: "Noto Sans SC", "Microsoft YaHei", system-ui, sans-serif; }
canvas { position: fixed; inset: 0; z-index: 1; width: 100%; height: 100%; pointer-events: none; }

.rain-experience { position: relative; z-index: auto; min-height: 300vh; max-width: 100%; overflow-x: clip; background: transparent; }
.atmosphere { position: fixed; inset: -1.5%; z-index: 0; pointer-events: none; transform: scale(1.015); transform-origin: center; background: linear-gradient(90deg, rgba(8,16,21,.76) 0%, rgba(10,19,24,.38) 40%, rgba(10,18,22,.25) 64%, rgba(8,15,19,.52) 100%), linear-gradient(180deg, rgba(18,28,34,.08), rgba(11,19,24,.38)), url("/creative-assets/rain-window-environment-v1.png") center 47% / cover no-repeat; filter: saturate(.76) contrast(1.04) brightness(.86); }
.atmosphere::before { content: ""; position: absolute; inset: 0; background: radial-gradient(ellipse at 58% 84%, rgba(218,158,96,.11), transparent 22%), radial-gradient(ellipse at 50% 36%, transparent 38%, rgba(5,10,13,.3) 100%); mix-blend-mode: screen; }
.atmosphere::after { content: ""; position: absolute; inset: 0; opacity: .07; background-image: repeating-linear-gradient(102deg, transparent 0 22px, rgba(226,235,232,.2) 23px, transparent 24px 45px); mask-image: linear-gradient(to bottom, #000, transparent 72%); }
.chapter { position: relative; z-index: 2; min-height: 100vh; padding: clamp(28px, 5vw, 72px); display: flex; align-items: center; }
.copy { position: relative; z-index: 3; width: min(520px, 46vw); text-wrap: balance; text-shadow: 0 2px 24px rgba(10,18,21,.34); }
.copy--opening { align-self: center; margin-left: clamp(0px, 5vw, 82px); }
.copy--resonance { margin-left: auto; margin-right: clamp(0px, 7vw, 120px); }
.copy--resolve { margin-left: clamp(0px, 8vw, 140px); padding-top: 8vh; }
.eyebrow { margin: 0 0 18px; color: #d6d9d5; font-size: 12px; letter-spacing: .2em; text-transform: uppercase; }
h1, h2 { margin: 0; font-family: "Noto Serif SC", "Songti SC", Georgia, serif; font-weight: 500; line-height: 1.08; letter-spacing: -.035em; }
h1 { max-height: 42vh; font-size: clamp(42px, 6.6vw, 92px); }
h2 { font-size: clamp(34px, 4.5vw, 68px); }
.lede, .copy > p:not(.eyebrow):not(.status) { max-width: 39em; margin: 24px 0 0; color: var(--muted); font-size: clamp(15px, 1.35vw, 19px); line-height: 1.8; }
.scroll-cue { display: inline-flex; gap: 14px; align-items: center; min-height: 46px; margin-top: 32px; color: var(--ink); font-size: 14px; text-decoration: none; border-bottom: 1px solid rgba(242,239,232,.42); }
.primary-action { min-width: 152px; min-height: 50px; margin-top: 30px; padding: 0 24px; border: 1px solid rgba(247,226,199,.68); border-radius: 999px; background: rgba(187,119,58,.2); color: #fff7eb; font: inherit; cursor: pointer; backdrop-filter: blur(8px); }
.primary-action:hover, .primary-action:focus-visible { background: rgba(203,138,76,.36); outline: 2px solid rgba(255,232,199,.38); outline-offset: 3px; }
.status { display: flex; align-items: center; gap: 9px; margin-top: 18px; color: #d9c5ad; font-size: 13px; letter-spacing: .05em; }
.status-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 14px rgba(222,157,91,.8); }
.webgl-fallback::after { content: ""; position: fixed; right: 5vw; top: 15vh; z-index: 1; width: min(48vw, 520px); aspect-ratio: 1; background: url("/creative-assets/rain-memory-recorder-v1.png") center / contain no-repeat; filter: drop-shadow(0 28px 50px rgba(10,15,18,.3)); }

@media (max-width: 720px) {
  .rain-experience { min-height: 320vh; }
  .chapter { min-height: 106vh; padding: 28px 22px 44px; align-items: flex-start; }
  .copy { width: 100%; max-width: 390px; }
  .copy--opening { margin: 7vh 0 0; }
  .copy--resonance { margin: 62vh 0 0; }
  .copy--resolve { margin: 10vh 0 0; padding: 0; }
  h1 { font-size: clamp(39px, 12.5vw, 60px); max-width: 9em; }
  h2 { font-size: clamp(34px, 10vw, 50px); }
  .lede { max-width: 22em; margin-top: 20px; }
  .scroll-cue { margin-top: 22px; }
  .webgl-fallback::after { top: 44vh; right: -3vw; width: 90vw; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}
